/* ekranlar/ortak-veri.js — paket ortak (isletme ajanı) toplu içerik: yasal belgeler, kurumsal metinler, destek (SSS, talepler, Görüş Bildir, iletişim). GMX.isletme ekranlar/isletme.js başına taşındı (15 Kas).
 * ÜRETİLDİ (elle değiştirme yerine üreticiyi çalıştır): scratchpad gen-ortak.mjs. Kaynaklar salt okunur:
 *  - Yasal: DadaGourmet-panel/database/seeders/varliklar/yasal/*.html + manifest.json (31 belge), grup sırası YasalBelgelerSeeder.php belgeler(), grup adları YasalOkumaServisi.php.
 *    Metin değiştirilmedi. Çıkarılan: "Durum: Taslak" paragrafı ve sürüm satırı (sürüm/yürürlük alanlarda). [unvan] [adres] [e-posta] Gastro/Gourmet künyesiyle dolduruldu;
 *    öteki [yer tutucu]lar ekranda çizilmez (GM.yasalMetin süzgeci). 21 belgenin gövdesi web'de de "hukuki inceleme sürecinde": bekliyor:true, yalnız kapsam paragrafı.
 *  - Kurumsal: dadagourmet-prototip hakkimizda, kunye, iletisim; Basın-Medya yalnız panelde (içerik yok → bekliyor).
 *  - Destek: hesabim/cozum-merkezi.mjs (SSS, hızlı çözümler, talepler, öneri formu), parcalar/kabuk/katman.html (Görüş Bildir).
 *  - İşletme: isletme/_veri.mjs (Mikla sahibi paneli; tarih farkları sabit an 13 Kasım 2026'ya çevrildi). */
window.GMX = window.GMX || {};
GMX.sirket = {"unvan":"Dada İst Ajans Hizmetleri Ticaret Limited Şirketi","adres":"Yavuz Sultan Selim Mah. No:52/B, Fatih/İstanbul 34083","eposta":"dadamentorcom@gmail.com"};
GMX.yasal = {"dizin":{"baslik":"Yasal Metinler","giris":"Dada Gourmet politika ve yasal bildirimleri bu merkezde toplanır.","not":"Güncel sürüm ve yürürlük tarihleri her belgede gösterilir.","ayak":"Yalnız yürürlükte ve yayınlanmış sürümler listelenir.","gruplar":[{"kod":"sozlesmeler_kullanim","baslik":"A. Sözleşmeler ve Kullanım","ikon":"file-signature","kalemler":["kullanim-kosullari","topluluk-kurallari","yas-siniri","hesap-politikasi"]},{"kod":"isletme_icerik","baslik":"B. İşletme, Değerlendirme ve İçerik","ikon":"store","kalemler":["isletme-listeleme","degerlendirme-politikasi","icerik-telif","isletme-dogrulama","isletme-itiraz","isletme-kaldirma","sahte-degerlendirme","telif-ihlali-bildirimi","itiraz"]},{"kod":"veri_guvenlik","baslik":"C. Veri, Konum ve Güvenlik","ikon":"user-shield","kalemler":["gizlilik","kvkk","cerez","konum-verisi","veri-basvurusu","ucuncu-taraf-servisler","veri-imha","veri-ihlali","guvenlik-bildirimi"]},{"kod":"ticari_seffaflik","baslik":"D. Ticari ve Şeffaflık","ikon":"scale-balanced","kalemler":["sorumluluk-reddi","etkinlik-sorumluluk","on-bilgilendirme","mesafeli-satis","iade-kosullari","isletme-sozlesmesi","editoryal-politika","sponsorluk-politikasi","erisilebilirlik"]}]},"metinler":{"kullanim-kosullari":{"baslik":"Kullanım Koşulları","ikon":"file-contract","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"İşbu Kullanım Koşulları; Dada Gourmet platformunu işleten [unvan] (\"Dada Gourmet\" veya \"Platform\") ile Platform'u ziyaret eden, üye olan veya Platform üzerinden içerik üreten gerçek kişi (\"Kullanıcı\") arasındaki ilişkiyi düzenler. Platform'u kullanmaya devam ederek bu koşulları kabul etmiş sayılırsınız.","bloklar":[["h2","1. Taraflar ve Konu"],["p","İşbu Kullanım Koşulları; Dada Gourmet platformunu işleten <strong>Dada İst Ajans Hizmetleri Ticaret Limited Şirketi</strong> (\"<strong>Dada Gourmet</strong>\" veya \"<strong>Platform</strong>\") ile Platform'u ziyaret eden, üye olan veya Platform üzerinden içerik üreten gerçek kişi (\"<strong>Kullanıcı</strong>\") arasındaki ilişkiyi düzenler. Platform'u kullanmaya devam ederek bu koşulları kabul etmiş sayılırsınız."],["p","Bu metin; <a href=\"#/yasal/isletme-listeleme\">İşletme Listeleme ve Veri Politikası</a> ile <a href=\"#/yasal/topluluk-kurallari\">Topluluk ve Değerlendirme Kuralları</a> metinlerine atıf yapar ve onlarla birlikte bir bütün oluşturur."],["h2","2. Tanımlar"],["ul",["<strong>Mekân kaydı</strong> — Platform'da listelenen gerçek ve tanımlanabilir ticari işletmeye ait bilgi sayfası.","<strong>İşletme sahibi</strong> — Bir mekân kaydı üzerinde sahiplik talebi (claim) doğrulanmış gerçek veya tüzel kişi.","<strong>Değerlendirme</strong> — Kullanıcının bir mekâna ilişkin puanı ve yorum metni.","<strong>Kullanıcı içeriği</strong> — Değerlendirme, mekân fotoğrafı, mekân önerisi, liste ve benzeri Kullanıcı tarafından yüklenen her tür içerik.","<strong>Rota</strong> — Dada Route üzerinden oluşturulan güzergâh önerisi."]],["h2","3. Platform'un Niteliği"],["p","Dada Gourmet bir <strong>mekân rehberi ve lezzet rotası platformudur</strong>. Platform, listelediği işletmelerin sunduğu ürün ve hizmetin sağlayıcısı, satıcısı veya aracısı değildir; işletme ile Kullanıcı arasındaki ilişkiye taraf olmaz."],["p","Bir işletmenin Platform'da listelenmesi, o işletme ile Dada Gourmet arasında ticari bir ilişki bulunduğu anlamına gelmez. Listeleme esasları <a href=\"#/yasal/isletme-listeleme\">İşletme Listeleme ve Veri Politikası</a>'nda düzenlenir."],["h2","4. Hesap Açma ve Hesabın Kullanımı"],["ul",["Üyelik sırasında verilen bilgilerin doğru ve güncel olması Kullanıcı'nın sorumluluğundadır.","Hesap kişiseldir; giriş bilgilerinin gizliliğinden ve hesap üzerinden yapılan işlemlerden Kullanıcı sorumludur.","Bir kişinin, değerlendirme veya oylama sonucunu etkilemek amacıyla birden fazla hesap açması yasaktır.","Yetkisiz erişim şüphesinde Kullanıcı derhal <strong>dadamentorcom@gmail.com</strong> adresine bildirimde bulunur."]],["h2","5. Onayların Ayrı Alınması"],["p","Üyelik sırasında Kullanım Koşulları ve <a href=\"#/yasal/gizlilik\">Gizlilik Politikası</a> onayı zorunludur. <strong>Konum izni ve pazarlama izni bu onaydan ayrı, isteğe bağlı ve tek tek verilir</strong>; hiçbiri üyeliğin ön şartı değildir. Konum izni verilmeden de Platform kullanılabilir — ayrıntı için <a href=\"#/yasal/konum-verisi\">Konum Verisi Politikası</a>."],["h2","6. Kullanıcı İçeriği ve Değerlendirmeler"],["p","Kullanıcı içeriğinin yayımlanma koşulları <a href=\"#/yasal/topluluk-kurallari\">Topluluk ve Değerlendirme Kuralları</a>'nda, içerik üzerindeki hak ve lisans ilişkisi ise <a href=\"#/yasal/icerik-telif\">İçerik ve Telif Politikası</a>'nda düzenlenmiştir. Kullanıcı, değerlendirme yazarken bu iki metne uymayı kabul eder."],["p","Değerlendirmeler Kullanıcı'nın kişisel görüşüdür; Dada Gourmet bu görüşleri benimsemez ve doğruluğunu taahhüt etmez."],["h2","7. Konum Verisi"],["p","Platform, yakındaki mekânları gösterme, rota planlama ve içerik kişiselleştirme amaçlarıyla konum verisi işleyebilir. Bu işleme yalnızca açık rızaya dayanır ve rıza her zaman geri çekilebilir. Amaç, kesinlik düzeyi, saklama süresi ve paylaşım koşulları <a href=\"#/yasal/konum-verisi\">Konum Verisi Politikası</a>'nda ayrıntılandırılmıştır."],["h2","8. Yasak Kullanımlar"],["ul",["Platform verisinin otomatik araçlarla toplu olarak çekilmesi, kopyalanması veya türev bir hizmette kullanılması.","Sahte hesap açmak, sahte veya menfaat karşılığı değerlendirme yazmak ya da yazdırmak.","Platform'un güvenlik önlemlerini aşmaya yönelik girişimler ve hizmeti aksatacak yükleme oluşturmak.","Üçüncü kişilerin kişilik, telif veya marka haklarını ihlal eden içerik yüklemek."]],["h2","9. Ücretli Hizmetler"],["p","Platform'un temel kullanımı ve mekânların listelenmesi ücretsizdir. Pro üyelik, sponsorlu listeleme, öne çıkarma ve işletme reklamı gibi ücretli hizmetlerin koşulları ayrı sözleşme ve bilgilendirme metinleriyle düzenlenir; bu hizmetlerden yararlanmak Platform'un ücretsiz kullanımının şartı değildir."],["p","Ücretli hizmet almak, bir işletmenin puanını, sıralamasını veya kendisi hakkındaki değerlendirmelerin akıbetini değiştirmez."],["h2","10. Fikri Mülkiyet"],["p","Platform'un tasarımı, yazılımı, veri tabanı yapısı, markası ve editoryal içerikleri Dada Gourmet'e aittir. Kullanıcı içeriğinin mülkiyeti Kullanıcı'da kalır; Platform'a tanınan kullanım lisansının kapsamı <a href=\"#/yasal/icerik-telif\">İçerik ve Telif Politikası</a>'nda tanımlanmıştır."],["h2","11. Sorumluluğun Sınırlandırılması"],["p","Mekân bilgilerinin güncelliği, işletmelerde sunulan hizmetin niteliği, gıda güvenliği ve hijyen, rota önerilerinin kullanımı ile etkinlik, bilet ve rezervasyon bilgilerine ilişkin sınırlamalar <a href=\"#/yasal/sorumluluk-reddi\">Sorumluluk Reddi</a> metninde düzenlenmiştir."],["h2","12. Hesabın Askıya Alınması ve Sonlandırılması"],["p","Bu koşulların veya Topluluk Kuralları'nın ihlali hâlinde içerik yayından kaldırılabilir, hesap geçici olarak askıya alınabilir veya sonlandırılabilir. Kullanıcı'nın bu karara itiraz hakkı saklıdır; itiraz başvuruları <strong>dadamentorcom@gmail.com</strong> adresinden yapılır ve <strong>[yanıt süresi]</strong> içinde sonuçlandırılır."],["p","Kullanıcı hesabını dilediği zaman kapatabilir. Hesap kapanışında yazılmış değerlendirmelerin akıbeti Kullanıcı'ya sorulur; seçenekler ve puan ortalamasına etkisi <a href=\"#/yasal/gizlilik\">Gizlilik Politikası</a>'nda açıklanmıştır."],["h2","13. Değişiklikler ve Versiyonlama"],["p","Her metnin başında yürürlük tarihi ve sürüm numarası gösterilir. Metin güncellendiğinde kayıtlı kullanıcılara bildirim gönderilir; esaslı değişiklikte yeniden onay istenir. Kabul edilen metnin sürümü ve kabul tarihi hesabınızın \"İzinlerim ve Onaylarım\" bölümünde görüntülenebilir."],["h2","14. Uygulanacak Hukuk ve İletişim"],["p","Bu koşullara Türk hukuku uygulanır. Uyuşmazlıklarda <strong>[yetkili mahkeme ve icra daireleri]</strong> yetkilidir."],["ul",["<strong>Unvan:</strong> Dada İst Ajans Hizmetleri Ticaret Limited Şirketi","<strong>Adres:</strong> Yavuz Sultan Selim Mah. No:52/B, Fatih/İstanbul 34083","<strong>MERSİS no:</strong> [MERSİS no]","<strong>Vergi dairesi / vergi no:</strong> [vergi dairesi / vergi no]","<strong>KEP adresi:</strong> [KEP adresi]","<strong>E-posta:</strong> dadamentorcom@gmail.com"]],["h2","15. İlgili Metinler"],["ul",["<a href=\"#/yasal/topluluk-kurallari\">Topluluk ve Değerlendirme Kuralları</a>","<a href=\"#/yasal/isletme-listeleme\">İşletme Listeleme ve Veri Politikası</a>","<a href=\"#/yasal/sorumluluk-reddi\">Sorumluluk Reddi</a>"]]]},"topluluk-kurallari":{"baslik":"Topluluk ve Değerlendirme Kuralları","ikon":"people-group","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Bu kurallar, Dada Gourmet'te değerlendirme yazarken, fotoğraf yüklerken ve mekân önerirken uymanız gereken kuralları belirler. Metnin muhatabı kullanıcıdır: neyi nasıl paylaşabileceğinizi ve kural ihlalinde ne olacağını anlatır.","bloklar":[["h2","1. Bu Kuralların Amacı"],["p","Bu kurallar, Dada Gourmet'te değerlendirme yazarken, fotoğraf yüklerken ve mekân önerirken uymanız gereken kuralları belirler. Metnin muhatabı <strong>kullanıcıdır</strong>: neyi nasıl paylaşabileceğinizi ve kural ihlalinde ne olacağını anlatır."],["p","Değerlendirmenin hukuki çerçevesi — hangi ifadenin korunduğu, işletmenin cevap hakkı, bir değerlendirmenin nasıl bildirileceği, kaldırma ve itiraz süreci ile puan ve sıralamanın nasıl işlediği — ayrı bir metinde düzenlenmiştir: <a href=\"#/yasal/degerlendirme-politikasi\">Değerlendirme ve Yorum Politikası</a>."],["p","Bu metin <a href=\"#/yasal/kullanim-kosullari\">Kullanım Koşulları</a>'nın ayrılmaz parçasıdır. Değerlendirme yazan her kullanıcı bu kuralları kabul etmiş sayılır."],["h2","2. Değerlendirme Yazma Koşulları"],["ul",["<strong>Kişisel deneyim zorunludur.</strong> Yalnızca kendi ziyaret ettiğiniz mekân hakkında değerlendirme yazabilirsiniz. Duyduğunuz, okuduğunuz veya bir başkasından aktarılan deneyim değerlendirme konusu yapılamaz.","<strong>Bağlantı beyanı.</strong> İşletme sahibi, ortağı, çalışanı veya yakını ile işletmenin rakibi konumundaki kişiler o işletmeye değerlendirme yazamaz.","<strong>Menfaat karşılığı değerlendirme yasaktır.</strong> Ücret, indirim, ikram veya başka bir menfaat karşılığında yazılan değerlendirme — kim tarafından yazdırıldığına bakılmaksızın — kaldırılır.","<strong>Tekrar sınırı.</strong> Aynı hesap, aynı işletmeye <strong>[değerlendirme sınırı]</strong> kadar değerlendirme yazabilir. Yeni bir ziyaretle güncellenen değerlendirme, yeni bir değerlendirme olarak değil düzenleme olarak kaydedilir.","<strong>Ziyaret beyanı.</strong> Değerlendirme gönderilirken mekânın ziyaret edildiği ve yaklaşık ziyaret tarihi beyan edilir."]],["h2","3. Yasak İçerik"],["ul",["<strong>Hakaret, iftira ve isnat</strong> niteliğindeki ifadeler; işletmeye, çalışanlarına veya diğer kullanıcılara yönelik aşağılayıcı dil.","<strong>Doğrulanamayan sağlık ve hijyen iddiaları</strong> — gıda zehirlenmesi, haşere, bozuk ürün gibi iddialar. Bu tür bir deneyim yaşadıysanız yetkili sağlık birimine bildirimde bulunmanız gerekir; Platform bu iddiaları doğrulayacak konumda değildir.","<strong>Çalışanların kimliğini ifşa eden</strong> ifadeler — ad, fiziksel tarif, vardiya bilgisi veya sosyal medya hesabı üzerinden hedef göstermek.","<strong>Deneyimle ilgisi olmayan içerik</strong> — siyasi, dini, ideolojik veya kişisel husumete dayalı ifadeler.","Reklam, spam, bağlantı yığını ve başka bir işletmeye yönlendirme.","Üçüncü kişilerin kişisel verilerini içeren fotoğraf ve metinler."]],["p","Bir ifadenin neden yasak sayıldığı — özellikle <strong>öznel görüş ile doğrulanamayan olgusal iddia</strong> arasındaki sınır — örnekleriyle <a href=\"#/yasal/degerlendirme-politikasi\">Değerlendirme ve Yorum Politikası</a>'nda açıklanmıştır. Yazarken tereddüde düşerseniz oradaki örneklere bakın."],["h2","4. Kural İhlalinde Uygulanan Yaptırımlar"],["ul",["İçeriğin yayından kaldırılması ve kullanıcıya gerekçeli bildirim.","Tekrarlanan ihlalde değerlendirme yazma yetkisinin geçici olarak kısıtlanması.","Organize veya menfaat karşılığı değerlendirme tespitinde hesabın askıya alınması veya sonlandırılması.","Her hâlde kullanıcının itiraz hakkı saklıdır; itiraz yolu <a href=\"#/yasal/degerlendirme-politikasi\">Değerlendirme ve Yorum Politikası</a> §5.3'te düzenlenmiştir."]],["h2","5. İlgili Metinler"],["ul",["<a href=\"#/yasal/degerlendirme-politikasi\">Değerlendirme ve Yorum Politikası</a> — değerlendirmenin hukuki çerçevesi, cevap hakkı, kaldırma ve itiraz, puan ve sıralama","<a href=\"#/yasal/icerik-telif\">İçerik ve Telif Politikası</a> — değerlendirme ve fotoğraf üzerindeki haklar","<a href=\"#/yasal/kullanim-kosullari\">Kullanım Koşulları</a>"]]]},"yas-siniri":{"baslik":"Yaş Sınırı ve Küçüklerin Korunması","ikon":"child","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Dada Gourmet üyeliği için aranan asgari yaş ve küçüklerin korunmasına ilişkin esaslar.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Dada Gourmet üyeliği için aranan asgari yaş ve küçüklerin korunmasına ilişkin esaslar."]]},"hesap-politikasi":{"baslik":"Hesap Askıya Alma ve Kapatma Politikası","ikon":"user-lock","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Hesabın hangi hâllerde askıya alınacağı veya sonlandırılacağı, kullanıcının kendi hesabını kapatma yolu ve kapanışta içeriğin akıbeti.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Hesabın hangi hâllerde askıya alınacağı veya sonlandırılacağı, kullanıcının kendi hesabını kapatma yolu ve kapanışta içeriğin akıbeti."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/kullanim-kosullari\">Kullanım Koşulları</a>","<a href=\"#/yasal/gizlilik\">Gizlilik Politikası</a>"]]]},"isletme-listeleme":{"baslik":"İşletme Listeleme ve Veri Politikası","ikon":"store","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Dada Gourmet, işletmeleri kendi talepleri olmadan listeleyen bir rehber platformudur. Bu metin, listelemenin hangi esasa dayandığını ve bir işletmenin kendi kaydı üzerinde hangi haklara sahip olduğunu yazılı hâle getirir.","bloklar":[["h2","1. Amaç"],["p","Dada Gourmet, işletmeleri kendi talepleri olmadan listeleyen bir rehber platformudur. Bu metin, listelemenin hangi esasa dayandığını ve bir işletmenin kendi kaydı üzerinde hangi haklara sahip olduğunu yazılı hâle getirir."],["h2","2. Listeleme Esası"],["ul",["<strong>Kamuya açık kaynaklar</strong> — işletmenin kendi internet sitesi ve sosyal medya hesapları, resmî kayıtlar, basılı ve dijital yayınlar.","<strong>Editör ziyareti ve araştırması</strong> — ekip tarafından yerinde veya kaynak taramasıyla derlenen bilgiler.","<strong>Kullanıcı önerisi</strong> — kullanıcıların bildirdiği mekânlar ve gönderdiği düzeltmeler; yayımlanmadan önce incelenir."]],["ul",["Bir işletmenin listelenmesi için <strong>başvuru yapması gerekmez</strong>.","Listeleme, işletme ile Dada Gourmet arasında <strong>ticari bir ilişki doğurmaz</strong>; ortaklık, temsil veya tavsiye anlamına gelmez.","Listeleme <strong>ücretsizdir</strong> ve Platform'un ücretli hizmetlerinden bağımsızdır. Ücretli hizmet almamak listelemeyi, almak da ayrıcalıklı bir konumu doğurmaz."]],["h2","3. Bilginin Doğruluğu"],["p","Adres, telefon, çalışma saatleri, fiyat aralığı, menü içeriği ve açık/kapalı durumu gibi bilgiler işletme tarafından her an değiştirilebilir. <strong>Dada Gourmet bu bilgilerin güncelliğini ve doğruluğunu garanti etmez.</strong>"],["p","Kullanıcılara, özellikle çalışma saatleri ve rezervasyon gerektiren durumlarda, ziyaret öncesinde işletmeyle doğrudan teyit etmeleri önerilir."],["p","Hatalı olduğunu düşündüğünüz bir bilgiyi her mekân sayfasındaki <strong>\"Mekân bilgisi hatalı\"</strong> bildirimiyle iletebilirsiniz; bu kanal işletme sahibi olmayan kullanıcılara da açıktır."],["h2","4. İşletmenin Hakları"],["p","İşletme; adres, telefon, çalışma saatleri, menü, fiyat aralığı ve fotoğraflarının düzeltilmesini talep edebilir. Talepler <strong>dadamentorcom@gmail.com</strong> adresinden veya işletme panelinden iletilir ve <strong>[yanıt süresi]</strong> içinde sonuçlandırılır. Düzeltme talebi için sahiplik doğrulaması şart değildir; ancak doğrulanmış işletmelerin talepleri öncelikli işlenir."],["p","İşletme sahibi, kaydın sahipliğini talep ederek işletme paneline erişebilir. Doğrulama şu yollardan biriyle yapılır:"],["ul",["Vergi levhası veya işletme belgesinin ibrazı","İşletme ruhsatı veya ticaret sicil kaydı","Kayıtta görünen işletme telefonu üzerinden doğrulama"]],["p","<strong>Doğrulama tamamlanmadan \"Doğrulandı\" rozeti gösterilmez.</strong> Rozet, işletmenin kalitesine değil yalnızca sahipliğin doğrulanmış olduğuna işaret eder."],["p","Sahipliği doğrulanmış işletme, kaydının listeden kaldırılmasını talep edebilir. Talep <strong>[inceleme süresi]</strong> içinde incelenir ve sonuç gerekçesiyle bildirilir."],["p","Talep <strong>kabul edilir</strong> — işletme kapanmışsa, kayıt başka bir işletmeye aitse, kayıtta düzeltilemeyen esaslı bir hata varsa veya kaydın devamı işletme açısından somut bir hukuka aykırılık doğuruyorsa."],["p","Talep <strong>reddedilebilir</strong> — kayıt yalnızca kamuya açık bilgiden oluşuyorsa, kaldırma talebinin gerekçesi olumsuz değerlendirmelerin görünürlükten çıkarılmasıysa veya işletme faal olmaya devam ediyorsa. Bu hâlde işletmeye düzeltme ve cevap hakkı yolları hatırlatılır."],["p","Kayıt kaldırıldığında kayda bağlı değerlendirmeler ve fotoğraflar da yayından kalkar."],["p","Sahipliği doğrulanmış işletme, kendisi hakkındaki her değerlendirmeye tek kez ve görünür şekilde cevap verebilir. Cevap hakkının kapsamı ve sınırları <a href=\"#/yasal/degerlendirme-politikasi\">Değerlendirme ve Yorum Politikası</a> §4'te düzenlenmiştir."],["p","İşletme, kural ihlali içerdiğini düşündüğü bir değerlendirmeyi gerekçesiyle bildirebilir. Bildirim gerekçeleri, inceleme süreci ve yazarın itiraz hakkı <a href=\"#/yasal/degerlendirme-politikasi\">Değerlendirme ve Yorum Politikası</a> §5'te açıklanmıştır. <strong>Olumsuz olması tek başına bir değerlendirmenin kaldırılma sebebi değildir.</strong>"],["h2","5. Ücretli Hizmetler ve Şeffaflık"],["ul",["Sponsorlu listeleme ve öne çıkarma hizmetleri \"Sponsorlu\" etiketiyle gösterilir.","Ücretli hizmet almak; işletmenin puanını, değerlendirme sayısını veya değerlendirmelerin akıbetini <strong>etkilemez</strong>.","Ücretli hizmetin koşulları ayrı bir işletme hizmet sözleşmesiyle düzenlenir."]],["h2","6. Talep Kanalları ve İletişim"],["p","Düzeltme, sahiplik, kaldırma ve cevap talepleri işletme paneli üzerinden açılır ve panelde durumu izlenebilir. Panel dışından yapılan başvurular için:"],["ul",["<strong>Unvan:</strong> Dada İst Ajans Hizmetleri Ticaret Limited Şirketi","<strong>Adres:</strong> Yavuz Sultan Selim Mah. No:52/B, Fatih/İstanbul 34083","<strong>KEP adresi:</strong> [KEP adresi]","<strong>E-posta:</strong> dadamentorcom@gmail.com"]],["h2","7. İlgili Metinler"],["ul",["<a href=\"#/yasal/topluluk-kurallari\">Topluluk ve Değerlendirme Kuralları</a>","<a href=\"#/yasal/sorumluluk-reddi\">Sorumluluk Reddi</a>","<a href=\"#/yasal/icerik-telif\">İçerik ve Telif Politikası</a>"]]]},"degerlendirme-politikasi":{"baslik":"Değerlendirme ve Yorum Politikası","ikon":"star-half-stroke","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Dada Gourmet'te değerlendirilen şey bir tarif değil, gerçek ve tanımlanabilir bir ticari işletmedir. Bir mekân hakkındaki değerlendirme, o işletmenin ticari itibarını doğrudan etkileyebilir ve kişilik hakları ile haksız rekabet alanına girebilir. Bu politika, kullanıcıların deneyimlerini serbestçe anlatabilmesi ile işletmelerin kişilik ve ticari haklarının korunması arasındaki dengeyi kurar.","bloklar":[["h2","1. Bu Politikanın Amacı"],["p","Dada Gourmet'te değerlendirilen şey bir tarif değil, <strong>gerçek ve tanımlanabilir bir ticari işletmedir</strong>. Bir mekân hakkındaki değerlendirme, o işletmenin ticari itibarını doğrudan etkileyebilir ve kişilik hakları ile haksız rekabet alanına girebilir. Bu politika, kullanıcıların deneyimlerini serbestçe anlatabilmesi ile işletmelerin kişilik ve ticari haklarının korunması arasındaki dengeyi kurar."],["p","Metnin muhatabı <strong>işletme ilişkisidir</strong>: bir değerlendirmenin hukuki çerçevesini, işletmenin hangi haklara sahip olduğunu ve uyuşmazlığın nasıl çözüleceğini düzenler. Kullanıcının uyması gereken davranış kuralları ayrı bir metindedir: <a href=\"#/yasal/topluluk-kurallari\">Topluluk ve Değerlendirme Kuralları</a>."],["h2","2. Değerlendirmenin Hukuki Niteliği"],["ul",["Değerlendirmeler ve puanlar, onları yazan kullanıcıların <strong>kişisel görüşüdür</strong>. Dada Gourmet bu görüşleri benimsemez ve doğruluğunu taahhüt etmez.","Platform, değerlendirmeleri yayımlayan aracı konumundadır; her değerlendirmeyi önceden denetleme yükümlülüğü altında değildir. Kendisine bildirilen kural ihlallerini bu metindeki usulle inceler.","Bir değerlendirmenin olumsuz olması tek başına kaldırma sebebi değildir. Kaldırma, ancak bu metindeki ölçütlerin karşılanması hâlinde söz konusu olur."]],["h2","3. Kritik Ayrım: Öznel Görüş ile Doğrulanamayan Olgusal İddia"],["p","Bu ayrım hem kullanıcıyı hem işletmeyi korur ve moderasyon kararlarının dayanağıdır."],["p","Beğeni, damak zevki ve kişisel izlenim bildiren ifadeler korunur; olumsuz olmaları kaldırma sebebi değildir."],["ul",["\"Yemek bana göre tuzluydu.\"","\"Porsiyon fiyatına göre küçük geldi.\"","\"Müzik sesi benim için yüksekti, sohbet edemedik.\"","\"Servis beklediğimden yavaştı.\""]],["p","Doğru ya da yanlış olduğu kanıtlanabilir nitelikte olan, ancak kanıtlanamayan iddialar hukuki risk taşır ve incelemeye alınır."],["ul",["\"Bu mekânda zehirlendim.\"","\"Mutfakta fare gördüm.\"","\"Etin tarihi geçmişti, dondurulmuş ürün taze diye satılıyor.\"","\"Sahibi vergi kaçırıyor.\""]],["p","Aynı deneyimi öznel biçimde anlatmak mümkündür: \"Yemekten sonra kendimi iyi hissetmedim\" ifadesi kişisel bir aktarımdır; \"bu mekânda zehirlendim\" ise işletmeye atfedilen ve kanıt gerektiren bir olgusal iddiadır."],["p","Moderasyon ekibi bir değerlendirmeyi beğenilip beğenilmediğine göre değil, bu ayrım üzerinden değerlendirir. Olumsuz ama öznel bir değerlendirme, işletmenin talebi üzerine kaldırılmaz."],["h2","4. İşletmenin Cevap Hakkı"],["p","Sahipliği doğrulanmış işletme, kendisi hakkındaki her değerlendirmeye <strong>tek kez ve görünür şekilde</strong> cevap verebilir. Cevap, değerlendirmenin altında \"İşletmenin cevabı\" etiketiyle yayımlanır ve puan ortalamasını etkilemez."],["p","Cevap hakkı, kaldırma talebinden önce sunulan mekanizmadır: çoğu uyuşmazlık işletmenin kendi açıklamasını yapabilmesiyle çözülür. Cevap metni de <a href=\"#/yasal/topluluk-kurallari\">Topluluk ve Değerlendirme Kuralları</a>'na tabidir; kullanıcıyı hedef gösteren veya kişisel verisini ifşa eden cevap yayımlanmaz."],["p","Sahiplik doğrulaması ve işletme panelinin kapsamı için <a href=\"#/yasal/isletme-listeleme\">İşletme Listeleme ve Veri Politikası</a>."],["h2","5. Değerlendirme Bildirme, Kaldırma ve İtiraz"],["p","Bir değerlendirmeyi hem diğer kullanıcılar hem de hakkında değerlendirme yazılan işletme bildirebilir. Bildirim gerekçesi, <a href=\"#/yasal/topluluk-kurallari\">Topluluk ve Değerlendirme Kuralları</a>'nın §2'sindeki yazma koşullarına veya §3'ündeki yasak içerik maddelerine aykırılıktır; gerekçe seti orada tek yerde tanımlıdır ve burada tekrarlanmaz."],["p","Bunlara ek olarak, değerlendirmenin <strong>başka bir işletmeye ait deneyimi anlattığı</strong> — yani yanlış mekân kaydına yazıldığı — gerekçesiyle de bildirim yapılabilir."],["p","Bildirim <strong>[inceleme süresi]</strong> içinde incelenir. Karar, gerekçesiyle birlikte hem bildirimi yapana hem değerlendirmeyi yazan kullanıcıya bildirilir. İnceleme sırasında değerlendirme, sonucu etkilemeyecek şekilde yayında kalabilir veya geçici olarak görünürlükten çıkarılabilir; hangi hâlin uygulandığı karar bildiriminde yazılır."],["p","Değerlendirmesi kaldırılan kullanıcı, karara <strong>[itiraz süresi]</strong> içinde itiraz edebilir. İtiraz, ilk kararı veren kişiden bağımsız olarak incelenir ve sonucu gerekçesiyle bildirilir."],["h2","6. Puan ve Sıralama Şeffaflığı"],["ul",["<strong>Ortalama puan</strong>, o mekânda yayında olan değerlendirmelerin puanlarından hesaplanır. Kaldırılan, kullanıcı tarafından silinen, hesap kapanışında çekilen veya incelemede görünürlükten çıkarılmış değerlendirmeler hesaba katılmaz ve değerlendirme sayısında görünmez.","<strong>Değerlendirme sayısı</strong> ortalamanın yanında gösterilir; tek bir değerlendirmeye dayanan ortalama ile çok sayıda değerlendirmeye dayanan ortalama aynı ağırlıkta okunmamalıdır.","<strong>Liste sıralaması</strong> şu ölçütlere dayanır: <strong>[sıralama kriterleri]</strong>.","<strong>Sponsorlu içerik</strong> her zaman \"Sponsorlu\" etiketiyle ve organik sonuçlardan ayırt edilebilir biçimde gösterilir. Sponsorluğun sıralamaya etkisi: <strong>[sponsorlu içeriğin sıralamaya etkisi]</strong>.","Ücretli hizmet almak bir işletmenin puanını yükseltmez ve olumsuz değerlendirmelerin kaldırılmasını sağlamaz."]],["h2","7. İlgili Metinler"],["ul",["<a href=\"#/yasal/topluluk-kurallari\">Topluluk ve Değerlendirme Kuralları</a> — değerlendirme yazma koşulları, yasak içerik, yaptırımlar","<a href=\"#/yasal/isletme-listeleme\">İşletme Listeleme ve Veri Politikası</a> — sahiplik doğrulaması, düzeltme ve kaldırma talepleri","<a href=\"#/yasal/kullanim-kosullari\">Kullanım Koşulları</a>"]]]},"icerik-telif":{"baslik":"İçerik ve Telif Politikası","ikon":"copyright","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Bu politika, Dada Gourmet'e yüklediğiniz her tür kullanıcı içeriğini kapsar:","bloklar":[["h2","1. Kapsam"],["p","Bu politika, Dada Gourmet'e yüklediğiniz her tür kullanıcı içeriğini kapsar:"],["ul",["Mekân fotoğrafları (dış cephe, iç mekân, tabak, menü fotoğrafı)","Değerlendirme metinleri ve puanlar","Mekân önerileri ve düzeltme bildirimleri","Oluşturduğunuz listeler, koleksiyonlar ve rota kayıtları","Profil fotoğrafı ve profil metni"]],["h2","2. Mülkiyet ve Platform'a Verilen Lisans"],["p","<strong>Telifinizi devretmezsiniz.</strong> Yüklediğiniz içeriğin mülkiyeti size aittir. İçeriği Platform'a yükleyerek Dada Gourmet'e; <strong>dünya çapında, süresiz, bedelsiz, münhasır olmayan, devredilebilir ve alt lisans verilebilir</strong> bir kullanım lisansı vermiş olursunuz."],["p","Bu lisans, içeriğin Platform'da ve Platform'un tanıtımında kullanılabilmesi için gereklidir; içerik üzerindeki haklarınızı sona erdirmez ve içeriği başka yerlerde kullanmanıza engel olmaz."],["h2","3. Lisansın Kapsadığı Kullanımlar"],["ul",["<strong>Yayınlama ve çoğaltma</strong> — mekân sayfasında, listelerde, arama sonuçlarında ve editoryal derlemelerde gösterme.","<strong>Uyarlama ve düzenleme</strong> — kırpma, yeniden boyutlandırma, sıkıştırma, kapak görseli olarak kullanma; metinde imla ve biçim düzeltmesi.","<strong>Çeviri</strong> — değerlendirme ve öneri metinlerinin başka dillere çevrilerek yayımlanması.","<strong>Format değiştirme</strong> — mobil uygulamaya, bültene, akış (feed) ve veri uçlarına taşıma.","<strong>Tanıtım ve pazarlama</strong> — Platform'un tanıtım materyalinde ve sosyal medya hesaplarında kullanma; bu kullanımda kullanıcı adınız kaynak olarak gösterilir."]],["p","Lisans, içeriğinizin bir işletmeye ait reklam materyaline dönüştürülmesini kapsamaz."],["h2","4. Beyan ve Taahhütleriniz"],["p","İçerik yükleyerek şunları beyan ve taahhüt edersiniz:"],["ul",["İçerik size aittir veya içeriği yayımlamaya yetkili olduğunuz.","İçeriğin üçüncü kişilerin telif, marka veya sair fikri mülkiyet haklarını ihlal etmediği.","<strong>Fotoğrafta yer alan kişilerden</strong> — diğer müşteriler ve işletme çalışanları dâhil — görüntülerinin yayımlanması için izin aldığınız.","Fotoğrafın çekildiği işletmenin, iç mekânda fotoğraf çekimine ilişkin bir yasağı varsa buna uyduğunuz.","Bu beyanlara aykırılıktan doğacak her tür talep ve zararın sorumluluğunun size ait olduğu."]],["h2","5. Fotoğrafta Yer Alan Üçüncü Kişiler"],["p","Bir fotoğrafta yer alan kişi, kendi görüntüsünün kaldırılmasını talep edebilir. Bu talep kişilik hakkı kapsamındadır ve <strong>dadamentorcom@gmail.com</strong> adresine yapılan başvuruyla değerlendirilir. Kimliği belirlenebilir üçüncü kişiler içeren fotoğraflar, talep hâlinde kaldırılır veya ilgili kısım maskelenir."],["p","Kalabalık ve genel mekân görünümü içindeki, kimliği ayırt edilemeyen kişiler bu kapsamın dışındadır."],["h2","6. İşletmeye Ait Görsel ve Marka Unsurları"],["p","İşletme logosu, menü tasarımı, tabela ve işletmenin kendi ürettiği tanıtım görselleri o işletmenin hakkındadır. Bu unsurlar Platform'da yalnızca işletmenin tanıtımı ve tanınması amacıyla kullanılır. Hak sahibi işletme, bir görselin kaldırılmasını veya kaynağının düzeltilmesini <a href=\"#/yasal/isletme-listeleme\">İşletme Listeleme ve Veri Politikası</a>'ndaki kanaldan talep edebilir."],["h2","7. Platform'un Hakları"],["p","Dada Gourmet, kullanıcı içeriğini düzenleme, kategorilendirme, öne çıkarma, görünürlükten çıkarma ve yayından kaldırma; ihlal hâlinde hesabı askıya alma yetkisine sahiptir. Bu yetkinin kullanılması gerekçe gösterme zorunluluğuna bağlı değildir; ancak kullanıcının karara itiraz hakkı her hâlde saklıdır ve itiraz süreci <a href=\"#/yasal/degerlendirme-politikasi\">Değerlendirme ve Yorum Politikası</a> §5.3'te düzenlenmiştir."],["p","Platform, içeriği yayımlama yükümlülüğü altında değildir; bir içeriğin yüklenmiş olması yayımlanacağı anlamına gelmez."],["h2","8. Neyin Korunduğu — Olgusal Bilgi ile Özgün Anlatım Ayrımı"],["p","Bir mekânın adı, adresi, telefonu, çalışma saatleri ve menüsünde yer alan yemeklerin adları <strong>olgusal bilgidir</strong> ve tek başına telif korumasına konu olmaz. Korunan unsur; fotoğrafın kendisi, değerlendirmenin özgün anlatımı ve editoryal metinlerin ifade biçimidir."],["p","Bu ayrım, \"bu bilgi bana ait\" temelli taleplerin nasıl değerlendirileceğini belirler: olgusal bilginin listelenmesine ilişkin talepler <a href=\"#/yasal/isletme-listeleme\">İşletme Listeleme ve Veri Politikası</a> kapsamında, özgün içeriğe ilişkin talepler bu metnin §9'u kapsamında ele alınır."],["h2","9. Telif İhlali Bildirimi"],["p","Hakkınızın ihlal edildiğini düşünüyorsanız <strong>dadamentorcom@gmail.com</strong> adresine başvurunuzu iletebilirsiniz. Başvuruda şunlar bulunmalıdır:"],["ul",["Hak sahibi olduğunuza dair beyan ve iletişim bilgileriniz","İhlal edildiğini düşündüğünüz içeriğin Platform'daki adresi","Hakkın dayanağı ve ihlalin gerekçesi"]],["p","Başvuru <strong>[inceleme süresi]</strong> içinde incelenir. İçeriği yükleyen kullanıcı bilgilendirilir ve karara karşı itiraz hakkını kullanabilir."],["h2","10. Hesap Kapanışında İçeriğin Akıbeti"],["p","Hesabınızı sildiğinizde yazdığınız değerlendirmelerin ne olacağı size sorulur:"],["ul",["<strong>Değerlendirmelerim kalsın</strong> — içerik yayında kalır, adınız \"Silinmiş kullanıcı\" olarak görünür.","<strong>Değerlendirmelerimin tamamı kaldırılsın</strong> — içerik yayından kalkar ve mekân puan ortalamasından düşülür."]],["p","Yüklediğiniz fotoğraflar için de aynı seçim geçerlidir. İşlem geri alınamaz; hesap silme talebinden sonraki 30 gün içinde giriş yaparak talebi iptal edebilirsiniz. Ayrıntı için <a href=\"#/yasal/gizlilik\">Gizlilik Politikası</a>."],["h2","11. İlgili Metinler"],["ul",["<a href=\"#/yasal/topluluk-kurallari\">Topluluk ve Değerlendirme Kuralları</a>","<a href=\"#/yasal/gizlilik\">Gizlilik Politikası</a>"]]]},"isletme-dogrulama":{"baslik":"İşletme Sahipliği Talep ve Doğrulama","ikon":"certificate","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"İşletme sahipliğinin talep edilmesi (claim), doğrulama için istenen belgeler ve doğrulama rozetinin hangi aşamada gösterileceği.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","İşletme sahipliğinin talep edilmesi (claim), doğrulama için istenen belgeler ve doğrulama rozetinin hangi aşamada gösterileceği."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/isletme-listeleme\">İşletme Listeleme ve Veri Politikası</a>"]]]},"isletme-itiraz":{"baslik":"İşletme İtiraz ve Cevap Hakkı","ikon":"reply","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"İşletmenin kendisi hakkındaki değerlendirmeye cevap verme hakkı ve bu hakkın yanında kullanabileceği itiraz yolları.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","İşletmenin kendisi hakkındaki değerlendirmeye cevap verme hakkı ve bu hakkın yanında kullanabileceği itiraz yolları."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/isletme-listeleme\">İşletme Listeleme ve Veri Politikası</a>","<a href=\"#/yasal/topluluk-kurallari\">Topluluk ve Değerlendirme Kuralları</a>"]]]},"isletme-kaldirma":{"baslik":"İşletme Kaldırma Talebi","ikon":"store-slash","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"İşletmenin listeden çıkarılma başvurusu, talebin hangi koşullarda kabul edileceği veya reddedilebileceği ve başvurunun durum takibi.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","İşletmenin listeden çıkarılma başvurusu, talebin hangi koşullarda kabul edileceği veya reddedilebileceği ve başvurunun durum takibi."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/isletme-listeleme\">İşletme Listeleme ve Veri Politikası</a>"]]]},"sahte-degerlendirme":{"baslik":"Sahte Değerlendirme ile Mücadele Politikası","ikon":"user-secret","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Sahte, menfaat karşılığı veya organize değerlendirmelerin tespit yaklaşımı ve tespit hâlinde uygulanan yaptırımlar.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Sahte, menfaat karşılığı veya organize değerlendirmelerin tespit yaklaşımı ve tespit hâlinde uygulanan yaptırımlar."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/topluluk-kurallari\">Topluluk ve Değerlendirme Kuralları</a>"]]]},"telif-ihlali-bildirimi":{"baslik":"Telif İhlali Bildirimi (Notice & Takedown)","ikon":"flag","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Fotoğraf ve metin için hak sahibi başvurusunun nasıl yapılacağı, başvuruda aranan bilgiler ve içeriği yükleyen kullanıcının karşı bildirim hakkı.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Fotoğraf ve metin için hak sahibi başvurusunun nasıl yapılacağı, başvuruda aranan bilgiler ve içeriği yükleyen kullanıcının karşı bildirim hakkı."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/icerik-telif\">İçerik ve Telif Politikası</a>"]]]},"itiraz":{"baslik":"İçerik Kaldırma İtiraz Süreci","ikon":"scale-unbalanced","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"İçeriği kaldırılan kullanıcının başvuru kanalı, itirazın nasıl incelendiği ve sonucun nasıl bildirileceği.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","İçeriği kaldırılan kullanıcının başvuru kanalı, itirazın nasıl incelendiği ve sonucun nasıl bildirileceği."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/topluluk-kurallari\">Topluluk ve Değerlendirme Kuralları</a>"]]]},"gizlilik":{"baslik":"Gizlilik Politikası","ikon":"user-shield","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Dada Gourmet platformunda işlenen kişisel veriler bakımından veri sorumlusu [unvan]'dır.","bloklar":[["h2","1. Veri Sorumlusu"],["p","Dada Gourmet platformunda işlenen kişisel veriler bakımından veri sorumlusu <strong>Dada İst Ajans Hizmetleri Ticaret Limited Şirketi</strong>'dır."],["ul",["<strong>Adres:</strong> Yavuz Sultan Selim Mah. No:52/B, Fatih/İstanbul 34083","<strong>MERSİS no:</strong> [MERSİS no]","<strong>KEP adresi:</strong> [KEP adresi]","<strong>E-posta:</strong> dadamentorcom@gmail.com"]],["p","Bu metin, verilerinizi nasıl işlediğimizi ve bunun üzerinde hangi kontrollere sahip olduğunuzu anlatır. Aydınlatma yükümlülüğünün mevzuat karşılığı için <a href=\"#/yasal/kvkk\">KVKK Aydınlatma Metni</a>'ne bakınız."],["h2","2. İşlediğimiz Veriler"],["ul",["<strong>Hesap verileri</strong> — ad, kullanıcı adı, e-posta, profil fotoğrafı.","<strong>İçerik verileri</strong> — yazdığınız değerlendirmeler, yüklediğiniz fotoğraflar, oluşturduğunuz listeler ve mekân önerileri.","<strong>Konum verileri</strong> — açık rızanız hâlinde konum bilginiz ve oluşturduğunuz rota kayıtları.","<strong>Kullanım ve teknik veriler</strong> — IP adresi, oturum kayıtları, cihaz ve tarayıcı bilgisi, görüntülenen sayfalar.","<strong>Ticari işlem verileri</strong> — ücretli bir hizmet alırsanız abonelik ve fatura bilgileri. Kart bilgileri Platform'da saklanmaz; ödeme kuruluşu tarafından tokenize edilir.","<strong>İletişim verileri</strong> — destek, bildirim ve itiraz başvurularınızın içeriği."]],["h2","3. İşleme Amaçları"],["ul",["Üyeliğin oluşturulması, hesabın yönetilmesi ve güvenliğinin sağlanması","Değerlendirme, fotoğraf ve önerilerin yayımlanması ve moderasyonu","Yakındaki mekânların gösterilmesi ve rota planlaması (açık rıza)","İçerik kişiselleştirme ve öneri üretimi (açık rıza)","Sahte ve manipüle değerlendirmelerin tespiti; kural ihlallerinin incelenmesi","Ücretli hizmetlerin sunulması, faturalandırma ve muhasebe yükümlülükleri","Pazarlama iletişimi (ayrı ve isteğe bağlı açık rıza)","Hukuki yükümlülüklerin yerine getirilmesi ve uyuşmazlıkların çözümü"]],["h2","4. Onayların Ayrı Alınması"],["p","Üyelik onayı tek kutuda toplanmaz:"],["ul",["<strong>Zorunlu:</strong> <a href=\"#/yasal/kullanim-kosullari\">Kullanım Koşulları</a> ve bu Gizlilik Politikası'nın kabulü.","<strong>İsteğe bağlı ve ayrı:</strong> konum izni. <strong>Konum izni üyeliğin şartı değildir</strong> ve verilmediğinde Platform çalışmaya devam eder.","<strong>İsteğe bağlı ve ayrı:</strong> pazarlama iletişimi izni. E-posta, uygulama içi bildirim ve pazarlama izinleri tek tek verilir ve tek tek geri alınır."]],["p","Verdiğiniz onayların hangi metnin hangi sürümüne ve hangi tarihe ait olduğu hesabınızın <strong>\"İzinlerim ve Onaylarım\"</strong> bölümünde kayıtlıdır."],["h2","5. Paylaşım ve Aktarım"],["ul",["<strong>Harita ve rota hizmeti sağlayıcısı</strong> — rota hesaplaması ve harita gösterimi için gerekli olduğu ölçüde. Bkz. <a href=\"#/yasal/konum-verisi\">Konum Verisi Politikası</a>.","<strong>Barındırma ve altyapı sağlayıcıları</strong> — hizmetin sunulması için zorunlu ölçüde.","<strong>Ödeme kuruluşu</strong> — yalnızca ücretli hizmet alındığında.","<strong>Yetkili kamu kurum ve kuruluşları</strong> — mevzuattan doğan talep hâlinde."]],["p","Değerlendirmeleriniz, kullanıcı adınız ve profil fotoğrafınızla birlikte <strong>herkese açık</strong> olarak yayımlanır. Bu, hizmetin niteliği gereğidir."],["p","Yurt dışına aktarım yalnızca mevzuatın öngördüğü güvenceler sağlanarak yapılır."],["h2","6. Saklama Süreleri"],["ul",["<strong>Hesap ve içerik verileri</strong> — hesap açık kaldığı sürece; hesap silindiğinde §8'deki seçime göre.","<strong>Anlık konum verisi</strong> — [saklama süresi — anlık konum]","<strong>Rota geçmişi</strong> — [saklama süresi — rota geçmişi]","<strong>İşlem güvenliği kayıtları</strong> — mevzuatın öngördüğü asgari süre boyunca.","<strong>Fatura ve muhasebe kayıtları</strong> — mevzuattaki zorunlu saklama süresi boyunca.","<strong>Moderasyon ve itiraz kayıtları</strong> — [saklama süresi — moderasyon kayıtları]"]],["p","Sürenin sonunda veriler silinir, yok edilir veya anonim hâle getirilir."],["h2","7. Haklarınız ve Bunları Kullandığınız Yer"],["p","Verileriniz üzerindeki kontrol hakkınız, hesabınızdaki bölümler üzerinden fiilen kullanılabilir:"],["ul",["<strong>Profil Bilgilerim</strong> — ad, kullanıcı adı ve avatarınızı düzeltme.","<strong>Giriş ve Güvenlik</strong> — şifre, iki adımlı doğrulama ve aktif oturumların görüntülenip sonlandırılması.","<strong>Değerlendirmelerim</strong> — yazdığınız yorumları görme, düzenleme ve silme.","<strong>Konum ve Gizlilik</strong> — konum izni, rota geçmişi ve profil görünürlüğü.","<strong>Bildirim Tercihlerim</strong> — e-posta, uygulama içi ve pazarlama izinlerinin ayrı ayrı yönetimi.","<strong>İzinlerim ve Onaylarım</strong> — kabul ettiğiniz metinler, sürümleri ve kabul tarihleri.","<strong>Verilerimi İndir</strong> — değerlendirme, liste ve rota verinizin makine tarafından okunabilir biçimde dışa aktarımı.","<strong>Hesabımı Sil</strong> — kalıcı silme ve değerlendirmelerin akıbeti seçimi."]],["p","Mevzuattan doğan haklarınızın tam listesi ve başvuru usulü için <a href=\"#/yasal/kvkk\">KVKK Aydınlatma Metni</a>'ne bakınız."],["h2","8. Hesap Silme ve Değerlendirmelerin Akıbeti"],["p","Hesabınızı silerken yazdığınız değerlendirmelerin ne olacağı size sorulur:"],["ul",["<strong>Değerlendirmelerim kalsın</strong> — yayında kalır, adınız \"Silinmiş kullanıcı\" olarak görünür.","<strong>Değerlendirmelerimin tamamı kaldırılsın</strong> — yayından kalkar."]],["p","Kaldırılan değerlendirmeler mekân puan ortalamasından da düşülür. İşlem geri alınamaz; talepten sonraki <strong>30 gün</strong> içinde giriş yaparak silme talebini iptal edebilirsiniz."],["h2","9. Güvenlik"],["p","Kişisel verilerin yetkisiz erişime, kayba ve hukuka aykırı işlenmeye karşı korunması için idari ve teknik tedbirler uygulanır; erişim yetkileri görev bazlı sınırlandırılır ve yönetim tarafındaki müdahaleler denetim günlüğüne kaydedilir."],["h2","10. Çerezler"],["p","Tarayıcınıza yerleştirilen çerezler ve benzeri teknolojiler ayrıca <a href=\"#/yasal/cerez\">Çerez Politikası</a>'nda açıklanmıştır."],["h2","11. Başvuru"],["p","Bu politikaya ilişkin talep ve sorularınızı <strong>dadamentorcom@gmail.com</strong> adresine iletebilirsiniz. Mevzuattan doğan haklara ilişkin başvurular en geç <strong>30 gün</strong> içinde sonuçlandırılır; diğer başvurular <strong>[yanıt süresi]</strong> içinde yanıtlanır."],["h2","12. İlgili Metinler"],["ul",["<a href=\"#/yasal/kvkk\">KVKK Aydınlatma Metni</a>","<a href=\"#/yasal/konum-verisi\">Konum Verisi Politikası</a>","<a href=\"#/yasal/cerez\">Çerez Politikası</a>"]]]},"kvkk":{"baslik":"KVKK Aydınlatma Metni","ikon":"shield-halved","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Bu aydınlatma metni, 6698 sayılı Kişisel Verilerin Korunması Kanunu (\"KVKK\") m.10 uyarınca, Dada Gourmet platformunu işleten veri sorumlusu tarafından hazırlanmıştır.","bloklar":[["h2","1. Veri Sorumlusunun Kimliği"],["p","Bu aydınlatma metni, 6698 sayılı Kişisel Verilerin Korunması Kanunu (\"<strong>KVKK</strong>\") m.10 uyarınca, Dada Gourmet platformunu işleten veri sorumlusu tarafından hazırlanmıştır."],["ul",["<strong>Unvan:</strong> Dada İst Ajans Hizmetleri Ticaret Limited Şirketi","<strong>Adres:</strong> Yavuz Sultan Selim Mah. No:52/B, Fatih/İstanbul 34083","<strong>MERSİS no:</strong> [MERSİS no]","<strong>Vergi dairesi / vergi no:</strong> [vergi dairesi / vergi no]","<strong>KEP adresi:</strong> [KEP adresi]","<strong>E-posta:</strong> dadamentorcom@gmail.com"]],["h2","2. İşlenen Kişisel Veri Kategorileri"],["ul",["<strong>Kimlik verisi</strong> — ad, soyad, kullanıcı adı.","<strong>İletişim verisi</strong> — e-posta adresi ve varsa telefon numarası.","<strong>Müşteri işlem verisi</strong> — ücretli hizmet alındığında abonelik, sipariş ve fatura kayıtları.","<strong>İşlem güvenliği verisi</strong> — IP adresi, oturum ve giriş kayıtları, cihaz ve tarayıcı bilgisi.","<strong>Konum verisi</strong> — açık rıza hâlinde konum bilgisi ve rota kayıtları.","<strong>Görsel veri</strong> — profil fotoğrafı ve yüklenen mekân fotoğrafları.","<strong>Kullanıcı içeriği</strong> — değerlendirme metinleri, puanlar, listeler, mekân önerileri.","<strong>Pazarlama verisi</strong> — açık rıza hâlinde iletişim tercihleri ve etkileşim kayıtları."]],["h2","3. İşleme Amaçları"],["ul",["Üyelik kaydının oluşturulması, hesabın yönetimi ve kimlik doğrulama","Değerlendirme, fotoğraf ve önerilerin yayımlanması, moderasyonu ve itiraz süreçlerinin yürütülmesi","Yakındaki mekânların gösterilmesi, rota planlaması ve içerik kişiselleştirme","Sahte ve manipüle değerlendirmelerin tespiti, Platform güvenliğinin sağlanması","Ücretli hizmetlerin sunulması, faturalandırma ve muhasebe süreçlerinin yürütülmesi","Talep, şikâyet ve veri sahibi başvurularının karşılanması","Pazarlama iletişiminin yürütülmesi","Hukuki yükümlülüklerin yerine getirilmesi ve uyuşmazlıkların takibi"]],["h2","4. Hukuki Sebepler"],["ul",["<strong>Sözleşmenin kurulması ve ifası</strong> (KVKK m.5/2-c) — üyelik, hesap yönetimi, ücretli hizmetler.","<strong>Hukuki yükümlülüğün yerine getirilmesi</strong> (m.5/2-ç) — mevzuattan doğan kayıt ve saklama yükümlülükleri.","<strong>Bir hakkın tesisi, kullanılması veya korunması</strong> (m.5/2-e) — moderasyon, itiraz ve uyuşmazlık kayıtları.","<strong>Meşru menfaat</strong> (m.5/2-f) — Platform güvenliği, sahte değerlendirme tespiti, hizmetin iyileştirilmesi.","<strong>Açık rıza</strong> (m.5/1) — konum verisinin işlenmesi ve pazarlama iletişimi. Bu iki rıza birbirinden ve üyelik onayından ayrı alınır; her biri ayrı ayrı geri çekilebilir."]],["h2","5. Toplama Yöntemi"],["p","Kişisel verileriniz; üyelik ve giriş formları, değerlendirme ve fotoğraf yükleme ekranları, konum izni akışı, iletişim ve başvuru formları, çerezler ile mobil uygulama üzerinden <strong>elektronik ortamda</strong>; yazılı başvurularda ise fiziksel ortamda toplanır."],["h2","6. Aktarım"],["p","Kişisel verileriniz KVKK m.8 ve m.9'a uygun olarak; hizmetin ifası için zorunlu olduğu ölçüde barındırma ve altyapı sağlayıcılarına, harita ve rota hizmeti sağlayıcısına, ödeme kuruluşuna ve yasal talep hâlinde yetkili kamu kurum ve kuruluşlarına aktarılabilir."],["p","Yurt dışına aktarım yalnızca Kanun'un öngördüğü şartların ve Kurul kararlarına uygun güvencelerin sağlanması hâlinde yapılır. Harita ve rota hizmetinin yurt dışında konumlu bir sağlayıcı üzerinden sunulması hâlinde bu durum <a href=\"#/yasal/konum-verisi\">Konum Verisi Politikası</a>'nda ayrıca açıklanır."],["h2","7. Saklama ve İmha"],["p","Veriler, işleme amacının gerektirdiği süre ve mevzuatta öngörülen azami süreler boyunca saklanır; sürenin sonunda periyodik imha dönemlerinde silinir, yok edilir veya anonim hâle getirilir. Kategori bazında süreler <a href=\"#/yasal/gizlilik\">Gizlilik Politikası</a> §6'da listelenmiştir."],["h2","8. İlgili Kişinin Hakları (KVKK m.11)"],["p","Veri sorumlusuna başvurarak şu haklarınızı kullanabilirsiniz:"],["ul",["Kişisel verinizin işlenip işlenmediğini öğrenme","İşlenmişse buna ilişkin bilgi talep etme","İşlenme amacını ve amacına uygun kullanılıp kullanılmadığını öğrenme","Yurt içinde veya yurt dışında verilerin aktarıldığı üçüncü kişileri bilme","Eksik veya yanlış işlenmiş verinin düzeltilmesini isteme","Kanun'un 7. maddesindeki şartlar çerçevesinde silinmesini veya yok edilmesini isteme","Düzeltme, silme ve yok etme işlemlerinin verilerin aktarıldığı üçüncü kişilere bildirilmesini isteme","Münhasıran otomatik sistemlerle analiz edilmesi suretiyle aleyhinize bir sonuç doğmasına itiraz etme","Kanuna aykırı işleme sebebiyle zarara uğramanız hâlinde zararın giderilmesini talep etme"]],["p","Açık rızaya dayalı işlemelerde (konum ve pazarlama) rızanızı dilediğiniz zaman geri çekebilirsiniz; geri çekme, o ana kadar yapılmış işlemenin hukuka uygunluğunu etkilemez."],["h2","9. Başvuru Yolu"],["p","Başvurularınızı, Veri Sorumlusuna Başvuru Usul ve Esasları Hakkında Tebliğ'e uygun olarak şu yollardan biriyle iletebilirsiniz:"],["ul",["Yazılı olarak <strong>Yavuz Sultan Selim Mah. No:52/B, Fatih/İstanbul 34083</strong> adresine","KEP adresinizden <strong>[KEP adresi]</strong> adresine","Sistemimizde kayıtlı e-posta adresinizden <strong>dadamentorcom@gmail.com</strong> adresine"]],["p","Başvurunuz talebin niteliğine göre en geç <strong>30 gün</strong> içinde ücretsiz olarak sonuçlandırılır. İşlemin ayrıca bir maliyet gerektirmesi hâlinde Kurul'ca belirlenen tarifedeki ücret alınabilir."],["h2","10. İlgili Metinler"],["ul",["<a href=\"#/yasal/gizlilik\">Gizlilik Politikası</a>","<a href=\"#/yasal/konum-verisi\">Konum Verisi Politikası</a>"]]]},"cerez":{"baslik":"Çerez Politikası","ikon":"cookie-bite","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Çerezler, ziyaret ettiğiniz sitelerin tarayıcınıza kaydettiği küçük metin dosyalarıdır. Bu politika, çerezlerin yanı sıra yerel depolama (localStorage) ve benzeri istemci tarafı saklama teknolojilerini de kapsar.","bloklar":[["h2","1. Çerez Nedir?"],["p","Çerezler, ziyaret ettiğiniz sitelerin tarayıcınıza kaydettiği küçük metin dosyalarıdır. Bu politika, çerezlerin yanı sıra yerel depolama (localStorage) ve benzeri istemci tarafı saklama teknolojilerini de kapsar."],["h2","2. Kullandığımız Çerez Kategorileri"],["p","Oturumun açık tutulması, güvenlik ve form gönderimlerinin doğrulanması için gereklidir. Bu çerezler olmadan Platform çalışmaz; bu nedenle rızaya bağlı değildir ve devre dışı bırakılamaz."],["p","Dil seçimi, görünüm tercihi, son kullanılan filtreler ve kayıtlı mekân listesi gibi tercihlerinizi hatırlar."],["p","Hangi sayfaların görüntülendiğini ve Platform'un nasıl kullanıldığını toplulaştırılmış biçimde ölçerek hizmeti iyileştirmemizi sağlar."],["p","Yalnızca ayrıca onay vermeniz hâlinde, ilgi alanınıza uygun içerik ve tanıtım göstermek için kullanılır."],["p","Harita görünümü ve son konum tercihiniz, sayfalar arasında kaybolmaması için tarayıcınızda saklanabilir. <strong>Bu saklama, konum verisinin işlenmesi için verilen açık rızanın yerine geçmez</strong>; konum verisinin işlenmesi <a href=\"#/yasal/konum-verisi\">Konum Verisi Politikası</a>'na tabidir."],["h2","3. Rıza Yönetimi"],["ul",["İlk ziyarette çerez bildirimi gösterilir; zorunlu çerezler dışındaki tüm kategoriler <strong>varsayılan olarak kapalıdır</strong>.","Kategorileri tek tek kabul edebilir veya reddedebilirsiniz; tümünü reddetmek Platform'un temel kullanımını engellemez.","Tercihinizi sonradan sayfa altındaki çerez ayarları bağlantısından değiştirebilirsiniz.","Rızanın verildiği tarih ve kapsam kaydedilir; rıza <strong>[çerez rızası geçerlilik süresi]</strong> sonunda yeniden sorulur."]],["h2","4. Tarayıcıdan Kontrol"],["p","Çerezleri tarayıcı ayarlarınızdan da yönetebilirsiniz: mevcut çerezleri silebilir, yeni çerezleri engelleyebilir veya her çerez öncesi uyarı isteyebilirsiniz. Zorunlu çerezlerin engellenmesi hâlinde oturum açma ve form gönderme gibi işlevler çalışmayabilir."],["h2","5. Üçüncü Taraf Hizmetleri"],["p","Harita gösterimi, rota hesaplaması, ölçümleme ve video oynatma gibi işlevler için üçüncü taraf hizmetler kullanılabilir. Bu hizmetlerin yerleştirdiği çerezler kendi politikalarına tabidir ve yalnızca ilgili kategoriye onay verdiğinizde yüklenir."],["h2","6. Saklama Süreleri"],["p","Oturum çerezleri tarayıcı kapatıldığında silinir. Kalıcı çerezlerin kategori bazındaki saklama süreleri: <strong>[çerez saklama süreleri]</strong>."],["h2","7. İlgili Metinler"],["ul",["<a href=\"#/yasal/gizlilik\">Gizlilik Politikası</a>","<a href=\"#/yasal/kvkk\">KVKK Aydınlatma Metni</a>"]]]},"konum-verisi":{"baslik":"Konum Verisi Politikası","ikon":"location-dot","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Konum verisi, kişinin nerede bulunduğunu ve zaman içinde nasıl hareket ettiğini ortaya koyduğu için özel dikkat gerektiren bir veri kategorisidir. Dada Gourmet konum izni istediği ve Dada Route üzerinden güzergâh verisi işlediği için bu konu ayrı bir metinde düzenlenmiştir.","bloklar":[["h2","1. Neden Ayrı Bir Metin?"],["p","Konum verisi, kişinin nerede bulunduğunu ve zaman içinde nasıl hareket ettiğini ortaya koyduğu için özel dikkat gerektiren bir veri kategorisidir. Dada Gourmet konum izni istediği ve Dada Route üzerinden güzergâh verisi işlediği için bu konu ayrı bir metinde düzenlenmiştir."],["h2","2. İşleme Amaçları — Her Amaç Ayrı"],["p","Konum veriniz yalnızca aşağıdaki amaçlarla ve her biri için ayrı ayrı verilen rızaya dayanarak işlenir:"],["p","Bulunduğunuz noktaya yakın mekânların listelenmesi ve mesafeye göre sıralanması. İşlenen kesinlik düzeyi: <strong>[kesinlik düzeyi — yakındaki mekânlar]</strong>."],["p","Başlangıç noktanızdan hedefe güzergâh hesaplanması ve güzergâh üzerindeki mekânların önerilmesi. İşlenen kesinlik düzeyi: <strong>[kesinlik düzeyi — rota planlama]</strong>."],["p","Anasayfa ve listelerdeki içeriğin bulunduğunuz bölgeye göre düzenlenmesi. İşlenen kesinlik düzeyi: <strong>[kesinlik düzeyi — içerik kişiselleştirme]</strong>."],["p","Bu amaçların dışında — örneğin profil çıkarma, reklam hedefleme veya üçüncü taraflara satış amacıyla — konum veriniz işlenmez."],["h2","3. Hukuki Dayanak: Açık Rıza"],["ul",["Konum verisinin işlenmesi <strong>yalnızca açık rızanıza</strong> dayanır.","Rıza, konumun ilk kez gerekli olduğu anda, ne için kullanılacağı açıklanarak istenir; tarayıcının veya işletim sisteminin izin penceresi tek başına rıza sayılmaz.","<strong>Konum izni üyelik onayına bağlanmaz.</strong> Üyelik sırasında zorunlu onay kutusunun içine dâhil edilmez.","Rızanızı dilediğiniz zaman geri çekebilirsiniz. Geri çekme ileriye etkilidir; o ana kadar yapılmış işlemenin hukuka uygunluğunu etkilemez."]],["h2","4. Saklama Süreleri"],["ul",["<strong>Anlık konum</strong> — [saklama süresi — anlık konum]","<strong>Rota geçmişi</strong> — [saklama süresi — rota geçmişi]"]],["p","Rızanızı geri çektiğinizde veya hesabınızı sildiğinizde konum kayıtlarınız silinir ya da anonim hâle getirilir."],["h2","5. Paylaşım"],["p","Rota hesaplaması ve harita gösterimi bir <strong>harita ve rota hizmeti sağlayıcısı</strong> üzerinden yapılır: <strong>[harita ve rota sağlayıcısı]</strong>. Bu işlem için başlangıç ve hedef noktalarınız sağlayıcıya iletilir. Sağlayıcının verileri kendi politikası kapsamında da işlemesi söz konusu olabilir; sağlayıcı yurt dışında konumluysa aktarım <a href=\"#/yasal/kvkk\">KVKK Aydınlatma Metni</a> §6'daki şartlara tabidir."],["p","Konum veriniz reklam ağlarıyla veya veri satışı amacıyla üçüncü kişilerle paylaşılmaz."],["h2","6. Kontrol — Konum Üzerindeki Yetkiniz"],["ul",["<strong>Konum iznini kapatma</strong> — hesabınızın \"Konum ve Gizlilik\" bölümünden veya tarayıcı/işletim sistemi ayarlarından.","<strong>Rota geçmişini silme</strong> — kayıtları tek tek veya toplu olarak silebilirsiniz.","<strong>Rızayı geri çekme</strong> — her amaç için ayrı ayrı; birini geri çekmek diğerlerini etkilemez.","<strong>Verilerimi İndir</strong> — rota ve konum kayıtlarınızı dışa aktarabilirsiniz."]],["h2","7. Konum İzni Verilmediğinde"],["p","<strong>Konum izni vermediğinizde Platform çalışmaya devam eder.</strong> Mekânları arayabilir, listeleri ve etkinlikleri görüntüleyebilir, değerlendirme yazabilir ve rota oluşturabilirsiniz; bu durumda başlangıç noktası konumunuzdan otomatik alınmak yerine tarafınızdan elle girilir."],["p","Konum izni verilmemesi hiçbir özelliğin tümüyle kapanmasına yol açmaz; yalnızca otomatik konum tespitine dayalı kolaylıklar devre dışı kalır."],["h2","8. Konum İzni İstenen Ekrandaki Aydınlatma"],["p","Konum izni istenen ekranda, iznin ne için kullanılacağı kısa ve anlaşılır biçimde açıklanır ve bu metnin tamamına bağlantı verilir. Kısa açıklama, bu metnin yerine geçmez; aydınlatmanın tam karşılığı bu metindir."],["h2","9. İlgili Metinler"],["ul",["<a href=\"#/yasal/kvkk\">KVKK Aydınlatma Metni</a>","<a href=\"#/yasal/gizlilik\">Gizlilik Politikası</a>","<a href=\"#/yasal/sorumluluk-reddi\">Sorumluluk Reddi</a> — rota önerileri ve sürüş güvenliği"]]]},"veri-basvurusu":{"baslik":"Veri Sahibi Başvuru Formu","ikon":"file-pen","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Erişim, düzeltme, silme ve taşınabilirlik taleplerinin iletileceği başvuru formu ve başvuruda aranan bilgiler.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Erişim, düzeltme, silme ve taşınabilirlik taleplerinin iletileceği başvuru formu ve başvuruda aranan bilgiler."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/kvkk\">KVKK Aydınlatma Metni</a>","<a href=\"#/yasal/gizlilik\">Gizlilik Politikası</a>"]]]},"ucuncu-taraf-servisler":{"baslik":"Harita ve Üçüncü Taraf Servisler Bildirimi","ikon":"map","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Harita gösterimi, rota hesaplaması, ölçümleme ve benzeri işlevler için kullanılan üçüncü taraf servisler ile bu servislere iletilen veriler.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Harita gösterimi, rota hesaplaması, ölçümleme ve benzeri işlevler için kullanılan üçüncü taraf servisler ile bu servislere iletilen veriler."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/konum-verisi\">Konum Verisi Politikası</a>","<a href=\"#/yasal/cerez\">Çerez Politikası</a>"]]]},"veri-imha":{"baslik":"Veri Saklama ve İmha Politikası","ikon":"trash-can","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Veri kategorileri bazında saklama süreleri ile periyodik imha, silme, yok etme ve anonim hâle getirme usulleri.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Veri kategorileri bazında saklama süreleri ile periyodik imha, silme, yok etme ve anonim hâle getirme usulleri."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/gizlilik\">Gizlilik Politikası</a>","<a href=\"#/yasal/kvkk\">KVKK Aydınlatma Metni</a>"]]]},"veri-ihlali":{"baslik":"Veri İhlali Bildirim Politikası","ikon":"triangle-exclamation","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Kişisel veri ihlali hâlinde uygulanacak müdahale prosedürü ile ilgili kişilere ve Kurul'a bildirim usulü.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Kişisel veri ihlali hâlinde uygulanacak müdahale prosedürü ile ilgili kişilere ve Kurul'a bildirim usulü."]]},"guvenlik-bildirimi":{"baslik":"Güvenlik Açığı Bildirimi","ikon":"bug","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Platform'da tespit edilen güvenlik açıklarının iletileceği kanal ve bildirimde bulunanlara ilişkin esaslar.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Platform'da tespit edilen güvenlik açıklarının iletileceği kanal ve bildirimde bulunanlara ilişkin esaslar."]]},"sorumluluk-reddi":{"baslik":"Sorumluluk Reddi","ikon":"circle-info","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Dada Gourmet bir mekân rehberi, etkinlik takvimi ve rota planlama platformudur. Platform'da yayımlanan bilgiler bilgilendirme amaçlıdır; Platform, listelediği işletmelerin sunduğu ürün ve hizmetin sağlayıcısı, satıcısı ya da aracısı değildir.","bloklar":[["h2","1. Genel"],["p","Dada Gourmet bir mekân rehberi, etkinlik takvimi ve rota planlama platformudur. Platform'da yayımlanan bilgiler <strong>bilgilendirme amaçlıdır</strong>; Platform, listelediği işletmelerin sunduğu ürün ve hizmetin sağlayıcısı, satıcısı ya da aracısı değildir."],["h2","2. Mekân Bilgileri"],["p","Adres, telefon, çalışma saatleri, fiyat aralığı, menü içeriği ve açık/kapalı durumu işletme tarafından her an değiştirilebilir. Bu bilgilerin güncelliği ve doğruluğu garanti edilmez. Ziyaret öncesinde, özellikle çalışma saatleri ve rezervasyon gerektiren durumlarda, işletmeyle doğrudan teyit edilmesi önerilir. Bilgilerin derlendiği kaynaklar ve düzeltme kanalı için <a href=\"#/yasal/isletme-listeleme\">İşletme Listeleme ve Veri Politikası</a>."],["h2","3. Hizmet, Gıda Güvenliği ve Hijyen"],["p","Platform, listelenen mekânlarda sunulan hizmetin niteliğinden, gıda güvenliğinden, hijyen koşullarından, alerjen içeriğinden ve bu koşullardan doğabilecek zararlardan <strong>sorumlu değildir</strong>. Bu sorumluluk ilgili işletmeye aittir. Alerji ve özel beslenme gereksinimlerinde bilgiyi işletmeden doğrudan teyit etmek kullanıcının sorumluluğundadır."],["p","Bir işletmenin Platform'da listelenmesi, denetlendiği, onaylandığı veya tavsiye edildiği anlamına gelmez."],["h2","4. Değerlendirmeler"],["p","Değerlendirmeler ve puanlar, onları yazan kullanıcıların <strong>kişisel görüşüdür</strong>. Dada Gourmet bu görüşleri benimsemez, doğruluğunu araştırmaz ve taahhüt etmez. Bir mekânın ortalama puanı, o mekân hakkında objektif bir yargı değil, yayında olan kullanıcı görüşlerinin toplamıdır."],["p","Kural ihlali içerdiğini düşündüğünüz bir değerlendirmeyi bildirebilirsiniz; süreç <a href=\"#/yasal/degerlendirme-politikasi\">Değerlendirme ve Yorum Politikası</a> §5'te açıklanmıştır."],["h2","5. Rota Önerileri ve Sürüş Güvenliği"],["ul",["Dada Route üzerinden üretilen güzergâhlar <strong>bilgilendirme amaçlıdır</strong>; yol durumu, trafik, yol çalışması, hava koşulları ve geçici kapanmalar nedeniyle gerçek durumdan farklı olabilir.","Önerilen güzergâhın uygunluğunun ve güvenliğinin değerlendirilmesi kullanıcıya aittir.","<strong>Trafik kurallarına uymak ve sürüş güvenliğini sağlamak kullanıcının sorumluluğundadır.</strong> Sürüş sırasında cihazla etkileşime girilmemeli; rota, araç hareket hâlindeyken incelenmemelidir.","Rota önerileri bir navigasyon veya seyir yardımı hizmeti değildir; araç tipi, yükseklik, ağırlık ve yol sınıfı kısıtlarını dikkate almaz.","Platform, rota önerisinin kullanımından doğan gecikme, zarar veya kazalardan sorumlu tutulamaz."]],["p","Konum verisinin nasıl işlendiği için <a href=\"#/yasal/konum-verisi\">Konum Verisi Politikası</a>."],["h2","6. Etkinlik Bilgileri"],["p","Etkinlik bilgileri düzenleyici kurum ve kuruluşların duyurularından derlenir. Tarih, saat, yer, program ve bilet bilgileri düzenleyici tarafından değiştirilebilir veya etkinlik iptal edilebilir. Platform bu bilgilerin doğruluğunu ve güncelliğini garanti etmez; katılım öncesinde düzenleyicinin resmî duyurusunun kontrol edilmesi önerilir."],["h2","7. Bilet ve Rezervasyon"],["p","Bilet satışı ve rezervasyon işlemleri <strong>üçüncü taraf platformlar veya doğrudan işletme üzerinden</strong> gerçekleşir. Dada Gourmet bu işlemlere taraf değildir; ödeme, iptal, iade ve katılım koşulları ilgili üçüncü tarafın kendi şartlarına tabidir. Bu işlemlerden doğan uyuşmazlıklarda muhatap ilgili üçüncü taraftır."],["h2","8. Üçüncü Taraf Bağlantıları"],["p","Platform'da yer alan dış bağlantılar kolaylık amacıyla sunulur. Bağlantı verilen sitelerin içeriği, gizlilik uygulamaları ve güvenliği o sitelerin sorumluluğundadır."],["h2","9. Bildirim Kanalı"],["p","Platform'da hatalı, hukuka aykırı veya haklarınızı ihlal eden bir içerik olduğunu düşünüyorsanız <strong>dadamentorcom@gmail.com</strong> adresine bildirimde bulunabilirsiniz. Bildirimler <strong>[inceleme süresi]</strong> içinde incelenir ve sonuç gerekçesiyle bildirilir."],["ul",["<strong>Unvan:</strong> Dada İst Ajans Hizmetleri Ticaret Limited Şirketi","<strong>Adres:</strong> Yavuz Sultan Selim Mah. No:52/B, Fatih/İstanbul 34083","<strong>KEP adresi:</strong> [KEP adresi]"]],["h2","10. İlgili Metinler"],["ul",["<a href=\"#/yasal/kullanim-kosullari\">Kullanım Koşulları</a>","<a href=\"#/yasal/isletme-listeleme\">İşletme Listeleme ve Veri Politikası</a>","<a href=\"#/yasal/konum-verisi\">Konum Verisi Politikası</a>"]]]},"etkinlik-sorumluluk":{"baslik":"Etkinlik Bilgileri Sorumluluk Reddi","ikon":"calendar-days","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Etkinlik tarih, yer, program ve bilet bilgilerinin düzenleyici kurumlardan derlendiğine ve değişebileceğine ilişkin ayrıntılı sorumluluk reddi.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Etkinlik tarih, yer, program ve bilet bilgilerinin düzenleyici kurumlardan derlendiğine ve değişebileceğine ilişkin ayrıntılı sorumluluk reddi."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/sorumluluk-reddi\">Sorumluluk Reddi</a>"]]]},"on-bilgilendirme":{"baslik":"Ön Bilgilendirme Formu (Pro)","ikon":"file-lines","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Ücretli üyelikte, ödeme adımından önce sunulan ön bilgilendirme.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Ücretli üyelikte, ödeme adımından önce sunulan ön bilgilendirme."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/kullanim-kosullari\">Kullanım Koşulları</a>"]]]},"mesafeli-satis":{"baslik":"Mesafeli Satış Sözleşmesi (Pro)","ikon":"file-signature","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Ücretli üyelik için kurulan mesafeli satış sözleşmesinin koşulları.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Ücretli üyelik için kurulan mesafeli satış sözleşmesinin koşulları."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/kullanim-kosullari\">Kullanım Koşulları</a>"]]]},"iade-kosullari":{"baslik":"İptal, Cayma ve İade Koşulları (Pro)","ikon":"rotate-left","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Ücretli üyelikte iptal, cayma hakkı ve iade koşulları.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Ücretli üyelikte iptal, cayma hakkı ve iade koşulları."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/kullanim-kosullari\">Kullanım Koşulları</a>"]]]},"isletme-sozlesmesi":{"baslik":"İşletme Hizmet Sözleşmesi","ikon":"handshake","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Sponsorlu listeleme, öne çıkarma ve reklam gibi ücretli işletme hizmetlerinin sözleşme koşulları.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Sponsorlu listeleme, öne çıkarma ve reklam gibi ücretli işletme hizmetlerinin sözleşme koşulları."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/isletme-listeleme\">İşletme Listeleme ve Veri Politikası</a>"]]]},"editoryal-politika":{"baslik":"Editoryal Onay ve Değerlendirme Kriterleri","ikon":"pen-nib","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Editör onayının hangi ölçütlere göre verildiği ve editör rozetinin ne anlama geldiği.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Editör onayının hangi ölçütlere göre verildiği ve editör rozetinin ne anlama geldiği."]]},"sponsorluk-politikasi":{"baslik":"Sponsorlu Listeleme ve Reklam Politikası","ikon":"rectangle-ad","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Sponsorlu içeriğin nasıl etiketlendiği, sıralamaya etkisi ve reklam ile organik içeriğin ayrımı.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Sponsorlu içeriğin nasıl etiketlendiği, sıralamaya etkisi ve reklam ile organik içeriğin ayrımı."],["h2","Bu Konu Şimdilik Nerede Düzenleniyor"],["p","Bu metin yürürlüğe girene kadar, konuya ilişkin yürürlükteki hükümler aşağıdaki metinlerde yer alır:"],["ul",["<a href=\"#/yasal/topluluk-kurallari\">Topluluk ve Değerlendirme Kuralları</a>","<a href=\"#/yasal/isletme-listeleme\">İşletme Listeleme ve Veri Politikası</a>"]]]},"erisilebilirlik":{"baslik":"Erişilebilirlik Beyanı","ikon":"universal-access","surum":"1.0","yururluk":"2026-08-15","guncelleme":"2026-08-15","ozet":"Dada Gourmet arayüzünün erişilebilirlik düzeyine ilişkin beyan.","bekliyor":true,"bloklar":[["h2","Bu Metnin Kapsamı"],["p","Dada Gourmet arayüzünün erişilebilirlik düzeyine ilişkin beyan."]]}}};
GMX.kurumsal = {"hakkimizda":{"etiket":"Keşif Hikâyemiz","baslik":"İyi bir sofra bulunmayı bekler.","gorsel":"assets/gorsel/hero/sokak-panorama.webp","alt":"Dada Gourmet; şehrin iyi sofralarını tesadüfe bırakmayan bir keşif rehberi. Mekânları editör süzgecinden geçiriyor, haritada gösteriyor ve gitmeye değer olanı öne çıkarıyoruz.","hikaye":{"etiket":"Nasıl Başladı","baslik":"Bir şehirde nereye gidileceğini bilmek, o şehri tanımaktır","paragraflar":["Dada Gourmet, **iyi bir mekânın tesadüfen bulunmaması** gerektiği fikriyle kuruldu. Bir sofranın hikâyesi, adresinden önce başlar: kim pişiriyor, hangi malzemeyle, hangi mahallede. Yol üstündeki küçük bir esnaf lokantasını da, rezervasyonu haftalar öncesinden dolan bir mutfağı da aynı dikkatle ele alıyoruz. Amacımız en pahalıyı değil, **gitmeye değeni** göstermek.","Bir rota düşündük; içinde sabah simitçisi de olsun, akşam şarap eşliği de. Keşif, bütçenin değil **merakın işi** olsun istedik. Bugün mekânları haritada gösteriyor, şehirler arası lezzet rotaları kuruyor ve yaklaşan gastronomi etkinliklerini **tek yerde** topluyoruz.","**Ne yapıyoruz?** Keşfi kolaylaştırıyoruz: mekânları konuma, mutfağa ve ortama göre filtrelenir hâle getiriyor; gideceğin yeri değil, o güne uygun **rotanın tamamını** planlamanı sağlıyoruz."]},"suzgec":{"baslik":"Editör süzgeci","metin":"Her mekân bilgisi doğrulanır; **sponsorlu içerik** açıkça işaretlenir."},"secim":{"etiket":"Pusulamız","baslik":"Nasıl seçiyoruz?","metin":"Bir mekânın listemize girmesi **üç aşamadan** geçer.","adimlar":[{"ikon":"user-pen","baslik":"Editör değerlendirmesi","metin":"Mekânı ekibimiz inceler: mutfağın tutarlılığı, ortam, fiyat-değer dengesi. Ücret karşılığı listeye giriş yoktur."},{"ikon":"circle-check","baslik":"Bilgi doğrulama","metin":"Adres, çalışma saati ve iletişim bilgisi kaynağından doğrulanır; kapanan ya da taşınan mekânlar güncellenir."},{"ikon":"comments","baslik":"Kullanıcı değerlendirmesi","metin":"Ziyaretçi yorumları editör notundan ayrı durur. Sponsorlu yerleşim ile editoryal içerik asla karışmaz."}]},"ihlal":"İçerik ihlali bildirimleri için **iletişim formunu** kullanabilirsin.","davet":{"etiket":"Birlikte Büyüyelim","baslik":"Bu rotada sana da yer var","kartlar":[{"ikon":"store","baslik":"İşletmeni Ekle","metin":"Restoran, kafe, otel ya da yerel üretici; mekânını değerlendirmeye gönder, editör süzgecinden geçsin.","git":"#/isletme"},{"ikon":"location-dot","baslik":"Mekânlar","metin":"Şehirdeki editör onaylı mekânları gez, kaydet ve kendi lezzet listeni oluştur.","git":"#/mekanlar"}]}},"kunye":{"etiket":"Resmî Bilgiler","baslik":"Künye","alt":"5651 sayılı kanun kapsamında yayıncı ve yer sağlayıcı bilgileri.","alanlar":[["building","Unvan","Dada İst Ajans Hizmetleri Ticaret Limited Şirketi"],["location-dot","Adres","Yavuz Sultan Selim Mah. No:52/B, Fatih/İstanbul 34083"],["envelope","E-posta","dadamentorcom@gmail.com"]],"not":"5651 sayılı kanun kapsamındaki yayıncı ve yer sağlayıcı bilgileri bu sayfada yayımlanır. **Bildirim ve taleplerini** iletişim formundan iletebilirsin."},"nasil-calisir":{"etiket":"Dada Gourmet","baslik":"Nasıl çalışır?","alt":"Mekânların listeye girişi ve **bildirimlerin** izlediği yol."},"basin":{"etiket":"Kurumsal","baslik":"Basın ve Medya","bekliyor":true,"alt":"Basın bülteni, logo ve görsel kiti yayımlandığında burada olacak. **Basın talepleri** için iletişim formunda Basın konusunu seç."}};
